package com.aadil.ecommerce.controllers;import com.aadil.ecommerce.dtos.InvitationDTO;import com.aadil.ecommerce.dtos.UserResponseDTO;import com.aadil.ecommerce.enums.UserSortDirection;import com.aadil.ecommerce.enums.UserSortField;import com.aadil.ecommerce.responses.APIResponse;import com.aadil.ecommerce.responses.PaginatedResponse;import com.aadil.ecommerce.services.AdminService;import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;import org.springframework.http.HttpStatus;import org.springframework.http.ResponseEntity;import org.springframework.validation.annotation.Validated;import org.springframework.web.bind.annotation.*;import java.security.NoSuchAlgorithmException;import java.time.LocalDateTime;import java.util.List;@RestController@RequestMapping ("/api/admin")@Validated@RequiredArgsConstructorpublic class AdminController {    private final AdminService adminService;    @PostMapping("/invitation-link")    public ResponseEntity<APIResponse<String>> adminInvitationLink (@Valid @RequestBody InvitationDTO dto) throws NoSuchAlgorithmException {        String inviteLink = adminService.adminInvitation(dto);        APIResponse<String> apiResponse = new APIResponse<>();        apiResponse.setSuccess(true);        apiResponse.setCode(201);        apiResponse.setMessage("Invitation link is created successfully");        apiResponse.setData(inviteLink);        apiResponse.setTimeStamp(LocalDateTime.now());        return new ResponseEntity<>(apiResponse, HttpStatus.CREATED);    }    @GetMapping("/all")    public ResponseEntity<APIResponse<PaginatedResponse<List<UserResponseDTO>>>> getAllUsers            (@RequestParam(required = false,name = "Search") String search,             @RequestParam (required = false, name = "PageNumber",defaultValue = "0") int pageNumber,             @RequestParam (required = false,name = "Size",defaultValue = "10") int size,             @RequestParam (required = false,name = "SortField",defaultValue = "ID") UserSortField userSortField,             @RequestParam (required = false,name = "SortDirection",defaultValue = "ASC") UserSortDirection sortDirection) {        PaginatedResponse<List<UserResponseDTO>> contents = adminService.getAllUsers(search,pageNumber,size,userSortField,sortDirection);        APIResponse<PaginatedResponse<List<UserResponseDTO>>> apiResponse = new APIResponse<>();        apiResponse.setSuccess(true);        apiResponse.setCode(200);        apiResponse.setMessage("All Users retrieved successfully");        apiResponse.setData(contents);        apiResponse.setTimeStamp(LocalDateTime.now());        return new ResponseEntity<>(apiResponse, HttpStatus.OK);    }    @DeleteMapping("/all/{ids}")    public ResponseEntity<APIResponse<Void>> deleteAllById (@PathVariable List<Long>ids, boolean confirm){        adminService.deleteUsersById(ids,confirm);        APIResponse<Void> apiResponse = new APIResponse<>();        apiResponse.setSuccess(true);        apiResponse.setCode(204);        apiResponse.setMessage("Selected users deleted successfully");        apiResponse.setMessage(null);        apiResponse.setTimeStamp(LocalDateTime.now());        return new ResponseEntity<>(apiResponse,HttpStatus.NO_CONTENT);    }    @DeleteMapping ("/{id}")    public ResponseEntity<APIResponse<Void>> deleteUser (@PathVariable Long id, @RequestParam boolean confirm){        adminService.deleteUser(id,confirm);        APIResponse<Void> apiResponse = new APIResponse<>();        apiResponse.setSuccess(true);        apiResponse.setCode(204);        apiResponse.setMessage("User deleted successfully");        apiResponse.setData(null);        apiResponse.setTimeStamp(LocalDateTime.now());        return new ResponseEntity<>(apiResponse,HttpStatus.NO_CONTENT);    }}